/**
 * @summary Upload user avatar
 */
export const getUploadAvatarUrl = (userId: number) => {
  return `/api/users/${userId}/avatar`;
};

export const uploadAvatar = async (
  userId: number,
  uploadAvatarBody: UploadAvatarBody,
  options?: RequestInit,
): Promise<MessageResponse> => {
  const formData = new FormData();
  if (uploadAvatarBody.avatar !== undefined) {
    formData.append(`avatar`, uploadAvatarBody.avatar);
  }

  return customFetch<MessageResponse>(getUploadAvatarUrl(userId), {
    ...options,
    method: "POST",
    body: formData,
  });
};

